import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/forge/commands.md","filePath":"modules/forge/commands.md","lastUpdated":0}`),a={name:`modules/forge/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiForge 的主命令是 <code>/emakiforge</code>，别名 <code>/eforge</code>、<code>/ef</code>。玩家用它打开锻造 GUI 或配方书；管理员用它重载配置、列出配方和查看运行状态。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><p>主命令本身需要 <code>emakiforge.use</code>（默认 true）。子命令的额外权限如下表。</p><table tabindex="0"><thead><tr><th>命令</th><th>说明</th><th>权限</th></tr></thead><tbody><tr><td><code>/ef help</code></td><td>显示帮助。无参数执行主命令时同样显示帮助。</td><td>仅需主命令权限。</td></tr><tr><td><code>/ef forge</code></td><td>打开锻造 GUI，仅玩家可执行。</td><td>仅需主命令权限。</td></tr><tr><td><code>/ef book</code></td><td>打开配方书，仅玩家可执行。</td><td><code>emakiforge.book</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef list recipe</code></td><td>列出已加载配方及显示名。<code>recipes</code> 也被接受，但 tab 只提示 <code>recipe</code>。</td><td><code>emakiforge.admin</code></td></tr><tr><td><code>/ef reload</code></td><td>重载配置、语言、GUI 模板和配方。</td><td><code>emakiforge.reload</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef convert-legacy [confirm]</code></td><td>当前 Forge 没有待执行的配置转换目标；命令只会按共享转换器流程报告无变更。材料和图纸应直接使用同级 <code>item_sources</code> + <code>matcher</code>（两者取 AND）。</td><td><code>emakiforge.admin</code></td></tr><tr><td><code>/ef debug stats</code></td><td>输出运行时指标与配方加载报告（<code>status</code> 等价）。</td><td><code>emakiforge.debug</code> 或 <code>emakiforge.admin</code></td></tr><tr><td><code>/ef debug &lt;player|module|...&gt;</code></td><td>转交 CoreLib 调试命令处理。</td><td><code>emakiforge.debug</code> 或 <code>emakiforge.admin</code></td></tr></tbody></table><p>可用的调试子模块：<code>recipe</code>、<code>forge</code>、<code>gui</code>、<code>pdc</code>。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to “权限节点”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakiforge.use</code></td><td>true</td><td>使用主命令与锻造 GUI。</td></tr><tr><td><code>emakiforge.book</code></td><td>true</td><td>打开配方书。</td></tr><tr><td><code>emakiforge.reload</code></td><td>op</td><td>重载配置。</td></tr><tr><td><code>emakiforge.debug</code></td><td>op</td><td>输出调试信息。</td></tr><tr><td><code>emakiforge.admin</code></td><td>op</td><td>管理员权限。</td></tr></tbody></table><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>玩家要锻造装备</td><td><code>/ef forge</code></td><td>打开锻造 GUI。</td></tr><tr><td>玩家找不到配方</td><td><code>/ef book</code></td><td>查看配方是否加载。</td></tr><tr><td>管理员改了配方或 GUI</td><td><code>/ef reload</code></td><td>重载 <code>recipes/</code>、<code>gui/</code>、语言和运行时资源。</td></tr><tr><td>不确定配方是否加载</td><td><code>/ef list recipe</code></td><td>查看当前加载的配方列表。</td></tr><tr><td>配方加载有告警或异常</td><td><code>/ef debug stats</code></td><td>查看运行时指标与配方加载报告。</td></tr><tr><td>锻造结果异常</td><td><code>/ef debug module forge</code></td><td>开启 forge 子模块调试输出。</td></tr></tbody></table><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to “使用场景”">​</a></h2><h3 id="玩家打开锻造界面" tabindex="-1">玩家打开锻造界面 <a class="header-anchor" href="#玩家打开锻造界面" aria-label="Permalink to “玩家打开锻造界面”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ef forge</span></span></code></pre></div><p>玩家在图纸槽放入图纸后，Forge 按图纸物品源匹配配方，再执行条件检查、容量检查、材料检查、品质计算和结果生成。</p><h3 id="玩家查看配方书" tabindex="-1">玩家查看配方书 <a class="header-anchor" href="#玩家查看配方书" aria-label="Permalink to “玩家查看配方书”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ef book</span></span></code></pre></div><p>配方书分页展示已加载配方。玩家看不到配方时，先用 <code>/ef list recipe</code> 确认配方是否加载。</p><h3 id="管理员重载" tabindex="-1">管理员重载 <a class="header-anchor" href="#管理员重载" aria-label="Permalink to “管理员重载”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ef reload</span></span></code></pre></div><p>修改 <code>recipes/</code>、<code>gui/</code> 或语言文件后使用。重载成功后会返回重载的配方数与 GUI 模板数。重载前建议先备份正在调试的配方文件。</p>`,20)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};